export interface ProfileNavGroup { label: string; items: { id: string; label: string; icon: React.ReactNode; dot?: boolean }[] }
export interface ProfileField { id: string; icon: React.ReactNode; label: string; value?: string; type?: "text" | "email" | "tel"; required?: boolean }
export type ProfileValues = Record<string, string>

export interface ProfilePageProps {
  coverSlot?: React.ReactNode
  initials: string
  name: string
  position: string
  department: string
  username: string
  roles: string[]
  lastAccess: string
  summaries: ProfileSummary[]
  nav: ProfileNavGroup[]
  activeNav: string
  onNavChange?: (id: string) => void
  fields: ProfileField[]
  /** Read-only "Công tác" fields shown in a second card (set by the administrator). */
  workFields?: ProfileField[]
  onEdit?: () => void
  onFieldAdd?: (id: string) => void
  /** Called with the validated values when the edit dialog is submitted. */
  onSave?: (values: ProfileValues) => void
  /** Footnote of the "Công tác" card. */
  workNote?: string
  /** Extra sections (password, PIN, certificate...) rendered under the "Công tác" card. */
  children?: React.ReactNode
}

export const profileDefaultIcons = { User, Briefcase, Phone, Mail, MapPin, Clock }


export function validateProfileValues(fields: ProfileField[], values: ProfileValues): ProfileValues {
  const errors: ProfileValues = {}
  for (const f of fields) {
    const v = (values[f.id] ?? "").trim()
    if (f.required && !v) errors[f.id] = `${f.label} không được để trống`
    else if (v && f.type === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) errors[f.id] = "Email không hợp lệ"
    else if (v && f.type === "tel" && !/^\+?[0-9 .]{9,13}$/.test(v)) errors[f.id] = "Số điện thoại không hợp lệ"
  }
  return errors
}

export function ProfilePage({ coverSlot, initials, name, position, department, username, roles, lastAccess, summaries, nav, activeNav, onNavChange, fields, workFields, onEdit, onFieldAdd, onSave, workNote = "Thông tin sai? Báo bộ phận hành chính hoặc quản trị hệ thống để điều chỉnh.", children }: ProfilePageProps) {
  const [values, setValues] = React.useState<ProfileValues>(() => Object.fromEntries(fields.map((f) => [f.id, f.value ?? ""])))
  const [draft, setDraft] = React.useState<ProfileValues>(values)
  const [errors, setErrors] = React.useState<ProfileValues>({})
  const [open, setOpen] = React.useState(false)
  const [focusId, setFocusId] = React.useState<string>()
  const [localNav, setLocalNav] = React.useState(activeNav)
  const current = onNavChange ? activeNav : localNav

  const openEdit = (id?: string) => { setDraft(values); setErrors({}); setFocusId(id); setOpen(true); if (id) onFieldAdd?.(id); else onEdit?.() }
  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    const errs = validateProfileValues(fields, draft)
    setErrors(errs)
    if (Object.keys(errs).length > 0) return
    const clean = Object.fromEntries(Object.entries(draft).map(([k, v]) => [k, v.trim()]))
    setValues(clean); setOpen(false); onSave?.(clean)
  }
  const display = (f: ProfileField) => values[f.id] || undefined

  const card = "rounded-[14px] border border-(--bd-ke) bg-(--bd-mat) shadow-[0_1px_2px_#2323380d,0_4px_16px_#2323380f]"
  const row = "grid min-h-[54px] grid-cols-[200px_minmax(0,1fr)_auto] items-center gap-4 border-t border-[#eef2f5] px-5 py-3 first:border-t-0 max-md:grid-cols-[minmax(0,1fr)_auto] max-md:gap-x-3 max-md:gap-y-1 max-md:px-4 dark:border-border"
  const label = "flex items-center gap-2 text-body text-(--bd-chu-3) max-md:col-span-full [&_svg]:size-4 [&_svg]:text-(--bd-mo)"
  const sectionHead = (icon: React.ReactNode, title: string, hint: string, action?: React.ReactNode) => (
    <div className="flex items-start gap-3 px-5 pt-[17px] pb-[15px] max-md:px-4">
      <span className="flex size-[34px] shrink-0 items-center justify-center rounded-[9px] bg-accent text-primary [&_svg]:size-[18px]">{icon}</span>
      <div className="min-w-0 flex-1"><h2 className="m-0 text-lead leading-[1.35] font-semibold text-(--bd-chu)">{title}</h2><p className="m-0 mt-0.5 text-small text-(--bd-chu-3)">{hint}</p></div>
      {action}
    </div>
  )
  return (
    <div className={cn(bdTokens, "pt-1 pb-24 text-(--bd-chu-2)")}>
      <section aria-label="Tóm tắt hồ sơ" className={cn(card, "overflow-hidden")}>
        <div className="relative h-[180px] overflow-hidden border-b border-(--bd-ke) bg-[#232338] max-md:h-[110px]">{coverSlot ?? <div className="size-full bg-[linear-gradient(135deg,#232338,#004998_60%,#3a9ad9)]" />}</div>
        <div className="flex items-start gap-5 px-6 pt-3.5 pb-[18px] max-md:flex-col max-md:gap-3 max-md:px-4 max-md:pt-0 max-md:pb-4">
          <div className="relative -mt-[62px] shrink-0 max-md:-mt-12">
            <Avatar className="size-24 border-4 border-white shadow-[0_2px_8px_#23233829]"><AvatarFallback className="border-0 bg-success text-4xl font-medium tracking-[0.02em] text-success-foreground">{initials}</AvatarFallback></Avatar>
            <button type="button" aria-label="Đổi ảnh đại diện" className="absolute right-0.5 bottom-1 flex size-[30px] cursor-pointer items-center justify-center rounded-full border-2 border-white bg-[#232338] p-0 text-white outline-none hover:bg-primary focus-visible:ring-2 focus-visible:ring-ring"><Camera className="size-[15px]" /></button>
          </div>
          <div className="min-w-0 flex-1">
            <h1 className="m-0 text-heading leading-[1.25] font-semibold tracking-[-0.01em] [overflow-wrap:anywhere] text-(--bd-chu)">{name}</h1>
            <p className="m-0 mt-[3px] text-control"><b className="font-medium text-(--bd-chu)">{position}</b><span className="mx-1.5 text-(--bd-mo)">·</span><span>{department}</span></p>
            <div className="mt-3 flex flex-wrap gap-1.5">
              <span className="inline-flex h-6 items-center rounded-md border border-(--bd-ke) bg-(--bd-mat-2) px-[9px] font-mono text-label whitespace-nowrap">@{username}</span>
              {roles.map((r) => <span key={r} className="inline-flex h-6 items-center rounded-md border border-border bg-accent px-[9px] text-xs font-medium whitespace-nowrap text-accent-foreground dark:border-border">{r}</span>)}
            </div>
          </div>
          <div className="flex shrink-0 flex-col items-end gap-2 max-md:w-full max-md:flex-row max-md:items-center max-md:justify-between">
            <span className="flex items-center gap-1 text-xs text-(--bd-chu-3)"><Clock className="size-3.5" />Truy cập lần cuối {lastAccess}</span>
            <Button variant="outline" onClick={() => openEdit()}><Pencil />Sửa hồ sơ</Button>
          </div>
        </div>
        <div className="grid grid-cols-1 border-t border-(--bd-ke) min-[560px]:grid-cols-2 lg:grid-cols-4">
          {summaries.map((s, i) => {
            const tone = s.tone ?? "primary"
            const ico = tone === "success" ? "bg-[#e4f4f2] text-success dark:bg-success/15 dark:text-success" : tone === "warning" ? "bg-[#fbf2e3] text-warning dark:bg-warning/15 dark:text-warning" : "bg-(--bd-mat-2) text-(--bd-chu-3)"
            return (
              <div key={s.id} className={cn("flex items-start gap-3 border-(--bd-ke) px-5 py-3.5 hover:bg-(--bd-mat-2) max-lg:border-b lg:border-r lg:last:border-r-0", i === summaries.length - 1 && "max-lg:border-b-0")}>
                <span className={cn("flex size-[34px] shrink-0 items-center justify-center rounded-[9px] [&_svg]:size-[18px]", ico)}>{s.icon}</span>
                <div className="flex min-w-0 flex-1 flex-col">
                  <span className="text-label font-semibold tracking-[0.03em] text-(--bd-chu-3) uppercase">{s.label}</span>
                  <span className={cn("mt-px text-sm font-semibold text-(--bd-chu)", tone === "warning" && "text-warning dark:text-warning")}>{s.value}</span>
                  {s.hint && <span className="mt-px text-xs leading-[1.4] text-(--bd-chu-3)">{s.hint}</span>}
                  {s.progress !== undefined && (
                    <div role="progressbar" aria-label={s.label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={s.progress} className={cn("mt-[7px] h-1 overflow-hidden rounded-full bg-(--bd-ke)", tone === "warning" ? "text-warning" : "text-success")}><div className="h-full rounded-[inherit] bg-current" style={{ width: `${s.progress}%` }} /></div>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      </section>
      <div className="mt-5 grid min-w-0 grid-cols-[216px_minmax(0,1fr)] items-start gap-6 max-lg:grid-cols-1 max-lg:gap-3">
        <nav aria-label="Hồ sơ" className={cn(card, "sticky top-2 flex max-h-[calc(100vh-8rem)] flex-col gap-0.5 overflow-y-auto px-2 py-2.5 max-lg:static max-lg:flex-row max-lg:gap-1.5 max-lg:overflow-x-auto max-lg:border-0 max-lg:bg-transparent max-lg:p-0 max-lg:shadow-none")}>
          {nav.map((g, gi) => (
            <div key={g.label} className="flex flex-col gap-0.5 max-lg:flex-row max-lg:gap-1.5">
              <p className={cn("m-0 px-2.5 pb-1.5 text-caption font-bold tracking-[0.06em] text-(--bd-mo) uppercase max-lg:hidden", gi === 0 ? "pt-1" : "pt-3")}>{g.label}</p>
              {g.items.map((i) => (
                <button key={i.id} type="button" aria-current={i.id === current ? "page" : undefined} onClick={() => { setLocalNav(i.id); onNavChange?.(i.id) }} className={cn("relative flex h-[38px] w-full cursor-pointer items-center gap-2.5 rounded-[9px] border-0 bg-transparent px-2.5 text-left text-control whitespace-nowrap text-(--bd-chu-2) outline-none transition-colors duration-[120ms] hover:bg-(--bd-mat-2) hover:text-(--bd-chu) focus-visible:shadow-focus max-lg:w-auto max-lg:shrink-0 max-lg:rounded-full max-lg:border max-lg:border-(--bd-ke) max-lg:bg-(--bd-mat) max-lg:text-body [&_svg]:size-[18px] [&_svg]:text-(--bd-mo)", i.id === current && "bg-accent font-semibold text-accent-foreground before:absolute before:top-2 before:bottom-2 before:-left-2 before:w-[3px] before:rounded-r-[3px] before:bg-primary before:content-[''] max-lg:border-primary max-lg:before:hidden [&_svg]:text-primary")}>
                  {i.icon}<span>{i.label}</span>{i.dot && <span aria-hidden className="ml-auto size-[7px] rounded-full bg-warning max-lg:ml-0" />}
                </button>
              ))}
            </div>
          ))}
        </nav>
        <div className="flex min-w-0 flex-col gap-4">
          <section className={card} aria-label="Thông tin cá nhân">
            {sectionHead(<User />, "Thông tin cá nhân", "Hiển thị trên hồ sơ, danh bạ nội bộ và văn bản bạn xử lý.", <Button variant="outline" size="sm" onClick={() => openEdit()}><Pencil />Sửa</Button>)}
            <dl className="m-0 border-t border-(--bd-ke)">
              {fields.map((f) => (
                <div key={f.id} className={row}>
                  <dt className={label}>{f.icon}{f.label}</dt>
                  <dd className={cn("m-0 min-w-0 text-sm [overflow-wrap:anywhere]", display(f) ? "text-(--bd-chu)" : "text-(--bd-mo) italic")}>{display(f) ?? "Chưa cập nhật"}</dd>
                  <div>{!display(f) && <Button variant="ghost" size="sm" onClick={() => openEdit(f.id)} aria-label={`Thêm ${f.label.toLowerCase()}`}>Thêm</Button>}</div>
                </div>
              ))}
            </dl>
          </section>
          {workFields && (
            <section className={card} aria-label="Công tác">
              {sectionHead(<Briefcase />, "Công tác", "Do quản trị hệ thống cấp — bạn không tự sửa được.")}
              <dl className="m-0 border-t border-(--bd-ke)">
                {workFields.map((f) => (
                  <div key={f.id} className={row}>
                    <dt className={label}>{f.icon}{f.label}</dt>
                    <dd className="m-0 min-w-0 text-sm text-(--bd-chu) [overflow-wrap:anywhere]">{f.value ?? "—"}</dd>
                    <div />
                  </div>
                ))}
                {roles.length > 0 && (
                  <div className={row}><dt className={label}>Vai trò</dt><dd className="m-0 flex flex-wrap gap-1.5">{roles.map((r) => <span key={r} className="inline-flex h-6 items-center rounded-md border border-border bg-accent px-[9px] text-xs font-medium text-accent-foreground dark:border-border">{r}</span>)}</dd><div /></div>
                )}
                <div className={row}><dt className={label}>Tên đăng nhập</dt><dd className="m-0 font-mono text-body text-(--bd-chu)">{username}</dd><div /></div>
              </dl>
              <div className="flex items-center gap-2 rounded-b-[14px] border-t border-(--bd-ke) bg-(--bd-mat-2) px-5 py-[11px] text-small text-(--bd-chu-3) max-md:px-4"><Lock className="size-[15px]" />{workNote}</div>
            </section>
          )}
          {children}
        </div>
      </div>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="p-0 sm:max-w-md">
          <DialogHeader><DialogTitle>Sửa hồ sơ</DialogTitle><DialogDescription>Cập nhật thông tin cá nhân hiển thị trên hồ sơ của bạn.</DialogDescription></DialogHeader>
          <form noValidate onSubmit={submit}>
            <div className="grid gap-4 px-[18px] py-4">
            {fields.map((f) => (
              <div key={f.id} className="grid gap-1.5">
                <Label htmlFor={`profile-${f.id}`}>{f.label}{f.required && <span aria-hidden className="text-destructive"> *</span>}</Label>
                <Input id={`profile-${f.id}`} type={f.type ?? "text"} autoFocus={f.id === focusId} value={draft[f.id] ?? ""} aria-invalid={errors[f.id] ? true : undefined} aria-describedby={errors[f.id] ? `profile-${f.id}-err` : undefined} onChange={(e) => setDraft((d) => ({ ...d, [f.id]: e.target.value }))} />
                {errors[f.id] && <p id={`profile-${f.id}-err`} role="alert" className="text-xs text-destructive">{errors[f.id]}</p>}
              </div>
            ))}
            </div>
            <DialogFooter><Button type="button" variant="outline" onClick={() => setOpen(false)}>Hủy</Button><Button type="submit">Lưu</Button></DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { bdShadow, bdTokens } from "./tokens"

export interface StatCardProps {
  label: string
  value: React.ReactNode
  /** Unit shown next to the value, e.g. "ngày". */
  unit?: string
  description?: React.ReactNode
  /** Mono reference line (e.g. a document code). */
  reference?: string
  /** Highlighted card uses the rose tone. */
  highlight?: boolean
  onClick?: () => void
  className?: string
}

/** Reference `dcs__o`: radius 14, padding 15/16/14, label 11.5/600, number 34/700, caption 11.5. */
export function StatCard({ label, value, unit, description, reference, highlight, onClick, className }: StatCardProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      data-highlight={highlight ? "true" : undefined}
      className={cn(
        bdTokens, bdShadow,
        "flex w-full cursor-pointer flex-col items-start rounded-[14px] border border-(--bd-ke) bg-(--bd-mat) px-4 pt-[15px] pb-3.5 text-left font-[inherit] text-inherit outline-none hover:border-(--bd-ke-2) focus-visible:ring-2 focus-visible:ring-ring",
        highlight && "border-(--bd-gap-line) bg-[linear-gradient(180deg,var(--bd-gap),var(--bd-mat)_60%)] hover:border-(--bd-t1)",
        className,
      )}
    >
      <span className="text-label font-semibold text-(--bd-chu-3)">{label}</span>
      <span className={cn("mt-1.5 text-display leading-[1.05] font-bold tracking-[-0.035em] tabular-nums", highlight ? "text-(--bd-t4)" : "text-foreground")}>
        {value}{unit ? <small className="ml-[3px] text-sm font-medium tracking-normal text-(--bd-chu-3)">{unit}</small> : null}
      </span>
      {reference ? <span className="mt-[3px] max-w-full truncate font-mono text-caption text-(--bd-chu-3)">{reference}</span> : null}
      {description ? <span className="mt-[3px] max-w-full truncate text-label text-(--bd-chu-3)">{description}</span> : null}
    </button>
  )
}

"use client"

// @dthu/ui 0.2.0 · block-dashboard
import * as React from "react"
import { cn } from "@/lib/utils"
import { bdTokens } from "./tokens"

export interface DashboardScheduleEvent { id: string; time: string; title: string; place?: string; /** Column of the event; defaults to the first leader. */ leaderId?: string; /** "S" (morning) or "C" (afternoon); defaults to the time of day. */ session?: "S" | "C" }
export interface DashboardWeekDay { id: string; label: string; date: string; today?: boolean; /** A day already gone: collapsed into one "Hiển thị" row while it has no events. */ past?: boolean; /** Saturday/Sunday rows get the muted background. */ weekend?: boolean; events: DashboardScheduleEvent[] }
export interface DashboardWeekLeader { id: string; name: string; role?: string }

export interface WeekScheduleGridProps {
  title: string
  days: DashboardWeekDay[]
  /** Columns of the grid (one per leader). A single "Lãnh đạo" column is used when omitted. */
  leaders?: DashboardWeekLeader[]
  /** Shown under the grid when the whole week has no events. */
  emptyText?: string
  pastLabel?: string
  className?: string
}

const sessions = ["S", "C"] as const
const sessionOf = (e: DashboardScheduleEvent) => e.session ?? (Number.parseInt(e.time.slice(0, 2), 10) < 12 ? "S" : "C")

const th = "border-b border-l border-(--bd-ke-2) border-l-(--bd-ke) bg-(--bd-mat-2) px-2.5 py-[10px] text-left align-top text-tiny font-semibold whitespace-nowrap text-(--bd-chu-2)"
const td = "min-w-32 border-b border-l border-(--bd-ke) px-[9px] py-[5px] align-top"

/** Weekly leadership schedule (reference `ltl__bang`): day column (76px) + session column (S/C, 24px) + one column per leader. */
export function WeekScheduleGrid({ title, days, leaders = [{ id: "all", name: "Lãnh đạo" }], emptyText = "Tuần này chưa có lịch công tác nào được đăng.", pastLabel = "Ngày đã qua, không có lịch", className }: WeekScheduleGridProps) {
  const [open, setOpen] = React.useState<Set<string>>(() => new Set())
  const empty = days.every((d) => d.events.length === 0)
  const toggle = (id: string) => setOpen((s) => { const n = new Set(s); if (n.has(id)) n.delete(id); else n.add(id); return n })
  return (
    <div className={cn(bdTokens, className)}>
      <div className="overflow-x-auto">
        <table aria-label={title} className="w-full border-collapse border-t border-(--bd-ke) text-small">
          <thead>
            <tr>
              <th colSpan={2} scope="col" className={cn(th, "border-l-0 text-center tracking-[0.1em] text-(--bd-chu-3) uppercase")}>Ngày</th>
              {leaders.map((l) => (
                <th key={l.id} scope="col" className={th}>{l.name}{l.role ? <span className="mt-px block text-micro font-normal tracking-normal text-(--bd-chu-3) normal-case">{l.role}</span> : null}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {days.map((d) => {
              const collapsed = !!d.past && d.events.length === 0 && !open.has(d.id)
              const rowBg = d.today ? "bg-(--bd-now)" : d.weekend ? "bg-(--bd-mat-2)" : ""
              const dayCell = (rowSpan?: number) => (
                <th scope="row" rowSpan={rowSpan} className={cn("w-[76px] min-w-[76px] border-b border-(--bd-ke) bg-(--bd-mat-2) text-center align-middle font-normal", collapsed ? "px-1 py-[5px]" : "px-[9px] py-[5px]", d.today && "bg-(--bd-now) shadow-[inset_3px_0_0_var(--bd-t3)]", d.weekend && !d.today && "bg-(--bd-mat-2)")}>
                  <b className="block text-xs font-semibold">{d.label}</b>
                  <span className="font-mono text-caption font-normal text-(--bd-chu-3)">{d.date}</span>
                  {d.today ? <em className="mt-0.5 block text-micro font-bold tracking-[0.08em] text-(--bd-t3) uppercase not-italic">hôm nay</em> : null}
                </th>
              )
              if (collapsed) {
                return (
                  <tr key={d.id}>
                    {dayCell()}
                    <td colSpan={leaders.length + 1} className="border-b border-(--bd-ke) bg-(--bd-mat-2) p-0 align-middle">
                      <button type="button" aria-expanded={false} onClick={() => toggle(d.id)} className="flex w-full cursor-pointer items-center gap-2 border-0 bg-transparent px-2.5 py-2 text-left text-xs text-(--bd-chu-3) outline-none hover:text-(--bd-s1) focus-visible:ring-2 focus-visible:ring-ring">{pastLabel}<span className="ml-auto text-label font-semibold text-(--bd-s1)">Hiển thị</span></button>
                    </td>
                  </tr>
                )
              }
              return sessions.map((s, si) => (
                <tr key={d.id + s}>
                  {si === 0 && dayCell(2)}
                  <td className={cn("w-6 min-w-6 border-b border-l border-(--bd-ke) bg-(--bd-mat-2) px-[9px] py-[5px] text-center align-top text-tiny font-bold text-(--bd-mo)", d.today && "bg-(--bd-now)")}>{s}</td>
                  {leaders.map((l, li) => {
                    const evs = d.events.filter((e) => sessionOf(e) === s && (e.leaderId ?? leaders[0]!.id) === l.id)
                    return (
                      <td key={l.id + li} className={cn(td, rowBg)}>
                        {evs.map((e) => (
                          <div key={e.id} className="my-0.5 rounded-sm border-l-[3px] border-(--bd-s1) bg-accent px-2 py-1 text-xs text-accent-foreground"><b className="font-mono font-semibold">{e.time}</b> {e.title}{e.place && <span className="block text-(--bd-chu-3)">{e.place}</span>}</div>
                        ))}
                      </td>
                    )
                  })}
                </tr>
              ))
            })}
          </tbody>
        </table>
      </div>
      {empty && <p className="m-0 flex items-center justify-center gap-2.5 border-t border-(--bd-ke) px-[18px] py-[22px] text-center text-body text-(--bd-chu-3)">{emptyText}</p>}
    </div>
  )
}

import * as React from "react"
import { Dialog as DialogPrimitive, Tabs as TabsPrimitive } from "radix-ui"
import { CalendarDays, CalendarX2, CircleCheckBig, SunMedium, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"

export interface WelcomeDialogItem { id: string; title: string; meta?: string }
export interface WelcomeDialogTab {
  id: string
  label: string
  items: WelcomeDialogItem[]
  emptyText?: string
  /** Heading of the panel (defaults to the label). */
  heading?: string
  /** Small text next to the heading, e.g. the long date. */
  subheading?: string
  /** Link at the right of the heading, e.g. "Xem lịch tuần →". */
  linkLabel?: string
  onLink?: () => void
  /** Icon of the tab (defaults to a calendar / check icon by position). */
  icon?: React.ReactNode
}
export interface WelcomeDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  greeting?: string
  userName: string
  /** Short date under the greeting, e.g. "Thứ Ba, 20/10/2026". */
  dateLabel?: string
  tabs: WelcomeDialogTab[]
  dontShowAgain?: boolean
  onDontShowAgainChange?: (v: boolean) => void
  startLabel?: string
}

const tabIcons = [<CalendarDays key="a" />, <CircleCheckBig key="b" />]

/**
 * Welcome bulletin shown after sign-in (reference `bt-modal`): 1080 x 86vh card, radius 16, 4px blue gradient bar on top,
 * greeting 18/700 with a sun icon, a 208px vertical tab rail and a footer with "Không hiện lại hôm nay" + the start button.
 * Full screen at <= 768px, where the rail becomes a row of pills.
 */
export function WelcomeDialog({ open, onOpenChange, greeting = "Chào buổi tối", userName, dateLabel, tabs, dontShowAgain = false, onDontShowAgainChange, startLabel = "Bắt đầu làm việc" }: WelcomeDialogProps) {
  return (
    <DialogPrimitive.Root open={open} onOpenChange={onOpenChange}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-overlay bg-[rgba(16,28,44,0.48)] anim-fade" />
        <DialogPrimitive.Content
          aria-describedby={undefined}
          className="fixed top-1/2 left-1/2 z-overlay flex h-[86vh] max-h-[86vh] w-[min(1080px,94vw)] -translate-x-1/2 -translate-y-1/2 flex-col overflow-hidden rounded-2xl bg-card text-base text-foreground shadow-[0_18px_48px_rgba(10,25,45,0.28)] focus:outline-none anim-pop max-md:top-0 max-md:left-0 max-md:h-dvh max-md:max-h-none max-md:w-screen max-md:translate-x-0 max-md:translate-y-0 max-md:rounded-none"
        >
          <div className="relative flex shrink-0 items-center gap-3 border-b border-border py-[18px] pr-[18px] pl-[22px] before:absolute before:inset-x-0 before:top-0 before:h-1 before:bg-[linear-gradient(90deg,#062449,#004998,#3a9ad9)] before:content-[''] dark:border-border">
            <DialogPrimitive.Title className="min-w-0 pb-0 text-[18px] leading-[1.3] font-bold max-md:text-base">
              <SunMedium aria-hidden className="mr-0.5 inline size-5 align-[-3px] text-[#e0a42a]" /> {greeting}, {userName}
              {dateLabel ? <small className="mt-0.5 block text-body font-medium text-muted-foreground dark:text-muted-foreground">{dateLabel}</small> : null}
            </DialogPrimitive.Title>
            <DialogPrimitive.Close aria-label="Đóng" title="Đóng" className="ml-auto inline-flex size-[34px] shrink-0 cursor-pointer items-center justify-center rounded-lg border-0 bg-transparent text-muted-foreground outline-none hover:bg-secondary hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring dark:hover:text-foreground"><X className="size-5" /></DialogPrimitive.Close>
          </div>
          <TabsPrimitive.Root defaultValue={tabs[0]?.id} orientation="vertical" className="grid min-h-0 w-full flex-1 grid-cols-[208px_1fr] max-md:grid-cols-1 max-md:grid-rows-[auto_1fr]">
            <TabsPrimitive.List aria-label="Nội dung bản tin" className="grid min-w-0 content-start gap-[3px] overflow-x-hidden overflow-y-auto border-r border-border bg-secondary px-2.5 py-3 max-md:flex max-md:gap-1.5 max-md:overflow-x-auto max-md:overflow-y-hidden max-md:border-r-0 max-md:border-b max-md:px-2.5 max-md:py-2 dark:bg-secondary">
              {tabs.map((t, i) => (
                <TabsPrimitive.Trigger key={t.id} value={t.id} className="flex w-full cursor-pointer items-center gap-2.5 rounded-[9px] border-0 bg-transparent px-[11px] py-2.5 text-left text-base font-semibold whitespace-nowrap text-muted-foreground outline-none hover:bg-card hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-primary data-[state=active]:bg-[#e6f0f7] data-[state=active]:text-primary max-md:w-auto max-md:shrink-0 max-md:rounded-full max-md:border max-md:border-border max-md:px-[11px] max-md:py-[7px] max-md:text-body dark:data-[state=active]:bg-accent [&_svg]:mx-0.5 [&_svg]:size-[18px] [&_svg]:shrink-0">
                  {t.icon ?? tabIcons[i % tabIcons.length]}<span className="truncate">{t.label}</span>
                </TabsPrimitive.Trigger>
              ))}
            </TabsPrimitive.List>
            <div className="min-h-0 overflow-y-auto px-6 py-5 [scrollbar-gutter:stable] max-md:p-4">
              {tabs.map((t) => (
                <TabsPrimitive.Content key={t.id} value={t.id} className="outline-none focus-visible:rounded-md focus-visible:shadow-focus">
                  <div className="mb-3.5 flex flex-wrap items-baseline gap-2.5">
                    <h3 className="m-0 text-title font-bold">{t.heading ?? t.label}</h3>
                    {t.subheading ? <span className="text-body text-muted-foreground dark:text-muted-foreground">{t.subheading}</span> : null}
                    {t.linkLabel ? <button type="button" onClick={t.onLink} className="ml-auto cursor-pointer border-0 bg-transparent p-0 text-body font-semibold text-primary hover:underline">{t.linkLabel}</button> : null}
                  </div>
                  {t.items.length === 0 ? (
                    <p className="m-0 rounded-xl border border-dashed border-[#cfd8e1] px-4 py-7 text-center text-control text-muted-foreground dark:border-border dark:text-muted-foreground"><CalendarX2 aria-hidden className="mx-auto mb-1 block size-7 text-[#95a3b1]" /> {t.emptyText ?? "Không có mục nào"}</p>
                  ) : (
                    <ul className="m-0 flex list-none flex-col divide-y p-0">
                      {t.items.map((i) => <li key={i.id} className="flex flex-col gap-0.5 border-l-[3px] border-primary/40 py-2.5 pl-3"><span className="text-sm font-medium">{i.title}</span>{i.meta && <span className="text-xs text-muted-foreground dark:text-muted-foreground">{i.meta}</span>}</li>)}
                    </ul>
                  )}
                </TabsPrimitive.Content>
              ))}
            </div>
          </TabsPrimitive.Root>
          <div className="flex shrink-0 flex-wrap items-center gap-3.5 rounded-b-2xl border-t border-border bg-secondary px-[18px] py-2.5 max-md:rounded-none">
            <label className="flex cursor-pointer items-center gap-[9px] py-1 text-base font-medium text-foreground"><Checkbox id="welcome-skip" checked={dontShowAgain} onCheckedChange={(c) => onDontShowAgainChange?.(c === true)} />Không hiện lại hôm nay</label>
            <span className="flex-1" />
            <Button onClick={() => onOpenChange(false)}>{startLabel}</Button>
          </div>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}
